'use client'

import React, { useEffect, useRef } from 'react'
import { cn } from '@/lib/utils/cn'

// Helper to convert hex to RGB
const hexToRgb = (hex: string) => {
  // Expand shorthand form (e.g. "03F") to full form (e.g. "0033FF")
  const shorthandRegex = /^#?([a-f\d])([a-f\d])([a-f\d])$/i
  const hexStr = hex.replace(shorthandRegex, (m, r, g, b) => r + r + g + g + b + b)
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hexStr)
  return result
    ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16),
      }
    : null
}

export interface GridPatternProps extends React.HTMLAttributes<HTMLDivElement> {
  theme?: 'light' | 'dark' | 'custom'
  // The background can be a valid CSS string like "#1e40af" or "linear-gradient(...)"
  background?: string
  // Custom box color hex (e.g. "#ffffff", "#000000", "#ff0000")
  boxColor?: string
}

export const GridPattern = React.forwardRef<HTMLDivElement, GridPatternProps>(
  ({ className, theme = 'dark', background, boxColor, ...props }, ref) => {
    const canvasRef = useRef<HTMLCanvasElement>(null)

    useEffect(() => {
      const canvas = canvasRef.current
      if (!canvas) return
      const ctx = canvas.getContext('2d')
      if (!ctx) return

      let animationFrameId: number

      const resize = () => {
        canvas.width = window.innerWidth
        canvas.height = window.innerHeight
      }

      window.addEventListener('resize', resize)
      resize()

      const TILE_SIZE = 18
      const BOX_SIZE = 10

      // ====================================================================
      // 🟢 1. ANIMATION SETTINGS (Tweak these to your liking!)
      // ====================================================================
      const RIPPLE_SPEED = 0.32
      const RIPPLE_SPREAD = 60
      const RIPPLE_SHARPNESS = 5
      // ====================================================================

      let time = 0

      const draw = () => {
        time += RIPPLE_SPEED
        ctx.clearRect(0, 0, canvas.width, canvas.height)

        const cols = Math.ceil(canvas.width / TILE_SIZE)
        const rows = Math.ceil(canvas.height / TILE_SIZE)

        for (let y = 0; y < rows; y++) {
          for (let x = 0; x < cols; x++) {
            const centerX = x * TILE_SIZE + TILE_SIZE / 2
            const centerY = y * TILE_SIZE + TILE_SIZE / 2

            const dx = centerX - canvas.width / 2
            const dy = centerY - canvas.height / 2
            const dist = Math.sqrt(dx * dx + dy * dy)

            // Calculate ripple phase
            const phase = (dist - time * 10) / RIPPLE_SPREAD
            const sine = Math.sin(phase) * 0.5 + 0.5 // Maps sine from 0 to 1

            // Math.pow shrinks the active wave width and expands the calm gap!
            const ripple = Math.pow(sine, RIPPLE_SHARPNESS)

            // Curved boxes
            ctx.beginPath()
            if (ctx.roundRect) {
              ctx.roundRect(
                centerX - BOX_SIZE / 2,
                centerY - BOX_SIZE / 2,
                BOX_SIZE,
                BOX_SIZE,
                2 // border radius
              )
            } else {
              ctx.rect(
                centerX - BOX_SIZE / 2,
                centerY - BOX_SIZE / 2,
                BOX_SIZE,
                BOX_SIZE
              )
            }

            // ====================================================================
            // 🟢 2. COLOR AND OPACITY SETTINGS
            // ====================================================================
            let r = 255, g = 255, b = 255

            // baseOpacity: opacity when the circle is NOT there (the calming empty space).
            // peakOpacity: opacity when the circle is at its brightest point.
            let baseOpacity = 0.05
            let peakOpacity = 0.40

            if (theme === 'light') {
              r = 0; g = 0; b = 0
              baseOpacity = 0.01
              peakOpacity = 0.08
            } else if (theme === 'dark') {
              r = 255; g = 255; b = 255
              baseOpacity = 0.015
              peakOpacity = 0.12
            } else {
              // "custom" mode
              baseOpacity = 0.05
              peakOpacity = 0.40
            }

            // Let user completely override the box color if they passed the `boxColor` prop
            if (boxColor) {
              const parsed = hexToRgb(boxColor)
              if (parsed) {
                r = parsed.r
                g = parsed.g
                b = parsed.b
              }
            }
            // ====================================================================

            const currentOpacity = (ripple * peakOpacity) + baseOpacity

            ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${currentOpacity})`
            ctx.fill()

            // Optional: outline
            ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${currentOpacity * 0.5})`
            ctx.stroke()
          }
        }

        animationFrameId = requestAnimationFrame(draw)
      }

      draw()

      return () => {
        window.removeEventListener('resize', resize)
        cancelAnimationFrame(animationFrameId)
      }
    }, [theme, boxColor])

    return (
      <div
        ref={ref}
        aria-hidden
        className={cn(
          'absolute inset-0 z-0 h-full w-full pointer-events-none overflow-hidden',
          className
        )}
        {...props}
      >
        {/* 1. Underlying background layer applying pure CSS background */}
        {background && (
          <div
            className="absolute inset-0 z-0 h-full w-full"
            style={{ background: background }}
          />
        )}

        {/* 1.5. Fallback backgrounds if none provided */}
        {!background && theme === 'light' && (
          <div className="absolute inset-0 z-0 h-full w-full bg-slate-50" />
        )}
        {!background && theme === 'dark' && (
          <div className="absolute inset-0 z-0 h-full w-full bg-neutral-950" />
        )}

        {/* 2. Grid canvas layer */}
        <canvas
          ref={canvasRef}
          className={cn(
            'block w-full h-full absolute inset-0 z-10',
            // The mix-blend-overlay is what makes the custom solid colors/gradients POP beautifully.
            theme === 'custom' && 'mix-blend-overlay'
          )}
        />
      </div>
    )
  }
)
GridPattern.displayName = 'GridPattern'

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
